#!/usr/bin/env bash
# ReBeL training: self-play games generated by the CFR search, in one command.
#
# Usage (from anywhere; the script cd's to the repository root):
#   ./src/rebel/run_training.sh                     # default run into checkpoints-rebel/
#   ./src/rebel/run_training.sh --smoke             # tiny run, no wandb (seconds)
#   ./src/rebel/run_training.sh --iterations 50 --games 8
#   ./src/rebel/run_training.sh --init-checkpoint checkpoints-rebel/best.pt
#
# Outputs land in checkpoints-rebel/ (policy_<iteration>.pt for every iteration and
# best.pt = the net with the best win rate against the heuristic bot). Metrics go to
# wandb project cuarenta-ai unless --no-wandb is passed.
#
# Cost, measured on a 10-core laptop at the defaults (n_iter=32, depth=3, particles=16):
# about 10s per self-play game -- a game is ~160 plies and a decision costs ~57ms of
# search -- so ~40s per iteration of 4 games, plus ~10-25s per evaluation (8 games over
# 4 workers). A 20-iteration run is therefore around 15 minutes; nearly all of it is the
# search, which is why --n-iter and --depth are the first knobs to turn down.

set -e

ROOT="$(cd "$(dirname "$0")/../.." && pwd)"
cd "$ROOT"

SAVE_DIR="${SAVE_DIR:-checkpoints-rebel}"
ITERATIONS="${ITERATIONS:-20}"
GAMES="${GAMES:-4}"
N_ITER="${N_ITER:-32}"
DEPTH="${DEPTH:-3}"
PARTICLES="${PARTICLES:-16}"
LR="${LR:-1e-3}"
DEVICE="${DEVICE:-cpu}"
EVAL_WORKERS="${EVAL_WORKERS:-4}"
EXTRA_ARGS=()

while [[ $# -gt 0 ]]; do
    case "$1" in
        --save-dir)   SAVE_DIR="$2"; shift 2 ;;
        --iterations) ITERATIONS="$2"; shift 2 ;;
        --games)      GAMES="$2"; shift 2 ;;
        --n-iter)     N_ITER="$2"; shift 2 ;;
        --depth)      DEPTH="$2"; shift 2 ;;
        --particles)  PARTICLES="$2"; shift 2 ;;
        --lr)         LR="$2"; shift 2 ;;
        --device)     DEVICE="$2"; shift 2 ;;
        --eval-workers) EVAL_WORKERS="$2"; shift 2 ;;
        --smoke)
            ITERATIONS=3; GAMES=2; N_ITER=4; DEPTH=2; PARTICLES=4
            EVAL_WORKERS=1; SAVE_DIR="/tmp/rebel_smoke"
            EXTRA_ARGS+=(--no-wandb --epochs 1 --eval-every 1 --eval-games 2)
            shift ;;
        -h|--help)
            sed -n '2,12p' "$0"
            exit 0 ;;
        *) EXTRA_ARGS+=("$1"); shift ;;
    esac
done

echo "ReBeL training config:"
echo "  iterations:       $ITERATIONS  (games=$GAMES per iteration)"
echo "  search:           n_iter=$N_ITER depth=$DEPTH particles=$PARTICLES"
echo "  lr:               $LR"
echo "  save dir:         $SAVE_DIR"
echo "  eval workers:     $EVAL_WORKERS"
echo "  device:           $DEVICE"
echo

python3 src/rebel/train.py \
    --iterations "$ITERATIONS" \
    --games "$GAMES" \
    --n-iter "$N_ITER" \
    --depth "$DEPTH" \
    --particles "$PARTICLES" \
    --lr "$LR" \
    --device "$DEVICE" \
    --save-dir "$SAVE_DIR" \
    --eval-workers "$EVAL_WORKERS" \
    "${EXTRA_ARGS[@]}"
